    public function test_route_permission_path_normalization()
    {
        // Test that /api/pekerjaan matches /pekerjaan
        RoutePermission::create([
            'route_path' => '/pekerjaan',

        // Test that /api/pekerjaan matches /pekerjaan
        RoutePermission::create([
            'route_path' => '/pekerjaan',
            'route_method' => 'GET',
            'allowed_roles' => ['admin'],
            'is_active' => true,
        ]);

        $user = User::factory()->create();
        $user->assignRole('user');

